//! Values generated by `build.rs` (random per build unless CI supplied a secret).

include!(concat!(env!("OUT_DIR"), "/built_secrets.rs"));

pub fn fingerprint() -> &'static str {
    BUILD_FINGERPRINT
}

pub fn embedded_cluster_secret() -> &'static str {
    EMBEDDED_CLUSTER_SECRET_HEX
}

pub fn description() -> String {
    format!(
        "promptsync {} build {} (embedded cluster secret: {})",
        env!("CARGO_PKG_VERSION"),
        BUILD_FINGERPRINT,
        if EMBEDDED_CLUSTER_SECRET_HEX.is_empty() {
            "no"
        } else {
            "yes"
        },
    )
}
